// Generate a valid filename with randomized contents. This satisfies the "path must be a valid file" requirement.
const char *path = FUZZ_PARAM_FILENAME();

// out-parameter for size must be non-null; use a local then persist via attribute for downstream unmapFile.
size_t outSize = 0;
size_t *size_cookie = new size_t(0); // will be set to the true size if mapping succeeds

// Call the target function.
void *data = mmapFile(path, &outSize);

// If mapping failed (unspecified convention, but NULL is typical), bail and avoid leaking the cookie.
if (!data) {
    delete size_cookie;
    FUZZ_BAIL();
}

// Persist mapping metadata on the returned opaque pointer for correctness in later stubs.
// - Track exact mapping size via a heap "cookie" to avoid integer truncation issues.
*size_cookie = outSize;
FUZZ_SET_ATTR_PTR(data, "size_cookie", (void*)size_cookie);

// - Track mapping state to enforce single unmap and prevent use-after-unmap.
FUZZ_SET_ATTR_INT(data, "is_mapped", 1);

// - Optionally retain the source path to aid debugging/correlation (not required for API correctness).
FUZZ_SET_ATTR_STR(data, "path", path);

// Validation summary:
// - Ensures non-null path and outSize pointer.
// - Bails on NULL return; otherwise, records size and mapping state for safe lifetime management.

// Enforce that this pointer represents a live mapping created by mmapFile.
int is_mapped = FUZZ_GET_ATTR_INT(data, "is_mapped");
if (!is_mapped) { FUZZ_BAIL(); }

// Retrieve the exact size captured at mapping time.
size_t *size_cookie = (size_t*)FUZZ_GET_ATTR_PTR(data, "size_cookie");
if (!size_cookie) { FUZZ_BAIL(); }
size_t size = *size_cookie;

// Call the target function to release the mapping.
unmapFile(data, size);

// Mark as unmapped to prevent double-unmap and use-after-free.
FUZZ_SET_ATTR_INT(data, "is_mapped", 0);

// Clean up auxiliary metadata now that the mapping is released.
delete size_cookie; // safe: mapping will not be returned to the pool

