import os
import random
import string
from typing import List

# This generator creates a valid file path string pointing to an on-disk file
# with interesting contents for mmapFile(path, &outSize).
# It ensures the path exists and is readable. No external deps, no network.

_MAX_TOTAL_SIZE = 4096

def _rand_rng(seed: int) -> random.Random:
    return random.Random(seed)

def _pick_dir(rng: random.Random) -> str:
    base = os.getcwd()
    depth = rng.choice([0, 1, 2])
    parts: List[str] = [base]
    for _ in range(depth):
        name = _random_safe_name(rng, rng.randint(3, 10))
        path = os.path.join(*parts, name)
        try:
            os.makedirs(path, exist_ok=True)
        except Exception:
            return base
        parts.append(path)
    return parts[-1]

def _random_safe_name(rng: random.Random, n: int) -> str:
    alphabet = string.ascii_letters + string.digits + "-_.@#%+="
    return ''.join(rng.choice(alphabet) for _ in range(n))

def _choose_extension(rng: random.Random) -> str:
    exts = [
        "", ".bin", ".txt", ".dat", ".log", ".json", ".cfg", ".tmp",
        ".img", ".map", ".zip"
    ]
    return rng.choice(exts)

def _gen_pattern_block(rng: random.Random, kind: str, size: int, align: int = 1) -> bytes:
    if size <= 0:
        return b""
    if kind == "zeros":
        return b"\x00" * size
    if kind == "ones":
        return b"\xFF" * size
    if kind == "ascii":
        # Printable ASCII with whitespace
        chars = (string.ascii_letters + string.digits + string.punctuation + " \n\t").encode()
        return bytes(rng.choice(chars) for _ in range(size))
    if kind == "seq":
        start = rng.randrange(256)
        return bytes((start + i) % 256 for i in range(size))
    if kind == "words":
        out = bytearray()
        a = rng.getrandbits(32).to_bytes(4, 'little')
        b = (~int.from_bytes(a, 'little') & 0xFFFFFFFF).to_bytes(4, 'little')
        tgt = max(align, 4)
        while len(out) < size:
            out += a if ((len(out) // tgt) % 2 == 0) else b
        return bytes(out[:size])
    if kind == "utf8":
        # Generate valid UTF-8 only; avoid surrogates (U+D800..U+DFFF)
        out = bytearray()
        while len(out) < size:
            choice = rng.random()
            if choice < 0.7:
                out.append(rng.randint(0x20, 0x7E))
            elif choice < 0.85:
                cp = rng.randint(0x80, 0x7FF)
                out += chr(cp).encode('utf-8')
            elif choice < 0.97:
                # select a 3-byte cp excluding surrogates
                while True:
                    cp = rng.randint(0x800, 0xFFFF)
                    if not (0xD800 <= cp <= 0xDFFF):
                        break
                out += chr(cp).encode('utf-8')
            else:
                cp = rng.randint(0x10000, 0x10FFFF)
                out += chr(cp).encode('utf-8')
        return bytes(out[:size])
    # default random
    return rng.randbytes(size)

def _compose_contents(rng: random.Random, target_size: int) -> bytes:
    min_size = 1
    target_size = max(min_size, min(target_size, _MAX_TOTAL_SIZE))

    segment_kinds = ["zeros", "ones", "ascii", "seq", "words", "utf8", "rand"]
    segs = []

    nseg = rng.randint(1, 6)
    remaining = target_size
    for i in range(nseg):
        kind = rng.choice(segment_kinds)
        if i == nseg - 1:
            size = remaining
        else:
            size = rng.choice([
                rng.randint(1, min(32, remaining)),
                rng.randint(33, min(512, remaining)) if remaining > 33 else 1,
                rng.randint(513, min(2048, remaining)) if remaining > 513 else 1,
                min(remaining, rng.choice([4096, 8192, 16384]))
            ])
            size = max(1, min(size, remaining))
        remaining -= size
        segs.append((kind, size))
        if remaining <= 0:
            break

    chunks: List[bytes] = []
    for kind, size in segs:
        align = rng.choice([1, 2, 4, 8])
        blk = _gen_pattern_block(rng, kind if kind != "rand" else "", size, align)
        if blk is None or len(blk) != size:
            blk = rng.randbytes(size)
        chunks.append(blk)

    data = b"".join(chunks)

    if rng.random() < 0.3:
        page = rng.choice([4096, 8192])
        pad_to = min(_MAX_TOTAL_SIZE, ((len(data) + page - 1) // page) * page)
        if pad_to > len(data):
            pad_kind = rng.choice(["zeros", "ones", "seq", "words"])
            data += _gen_pattern_block(rng, pad_kind, pad_to - len(data))

    if not data:
        data = b"X"
    return data[:_MAX_TOTAL_SIZE]

def _maybe_sparse_write(path: str, rng: random.Random, data: bytes) -> None:
    try:
        with open(path, 'wb') as f:
            mode = rng.random()
            if mode < 0.25 and len(data) > 64:
                head = data[: len(data)//4]
                tail = data[-len(data)//4:]
                f.write(head)
                hole = rng.randint(1, min(65536, 4 * len(data)))
                f.seek(hole, os.SEEK_CUR)
                f.write(tail)
            elif mode < 0.5 and len(data) > 0:
                off = rng.randint(1, 4096)
                f.seek(off, os.SEEK_SET)
                f.write(data)
            else:
                f.write(data)
    except Exception:
        with open(path, 'wb') as f:
            f.write(data)

def _build_path(rng: random.Random) -> str:
    directory = _pick_dir(rng)
    base = _random_safe_name(rng, rng.randint(5, 16))
    ext = _choose_extension(rng)
    if rng.random() < 0.3:
        base = base + rng.choice([".", "..", ".hidden"]) 
        base = base.replace("/", "_")
    filename = base + ext
    path = os.path.join(directory, filename)
    if len(path) > 240:
        filename = filename[:16] + ext
        path = os.path.join(directory, filename)
    return path

def generate(seed: int) -> bytes:
    rng = _rand_rng(seed)

    size_choice = rng.random()
    if size_choice < 0.15:
        target_size = rng.randint(1, 64)
    elif size_choice < 0.35:
        target_size = rng.randint(65, 1024)
    elif size_choice < 0.8:
        target_size = rng.randint(1025, 4096)
    else:
        target_size = 4096

    data = _compose_contents(rng, target_size)

    path = _build_path(rng)

    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)

    _maybe_sparse_write(path, rng, data)

    return path.encode('utf-8')

import random
import struct
from typing import List

# Generator for valid arbitrary binary file data to be used by FUZZ_PARAM_FILENAME.
# Produces deterministic-by-seed, varied contents up to 4096 bytes.

MAX_SIZE = 4096
PAGE = 4096


def _rand(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _pattern_repeat(byte_val: int, length: int) -> bytes:
    return bytes([byte_val]) * length


def _alternating(a: int, b: int, length: int) -> bytes:
    out = bytearray(length)
    for i in range(length):
        out[i] = a if (i & 1) == 0 else b
    return bytes(out)


def _rle_segments(rng: random.Random, total: int) -> bytes:
    # Build run-length encoded style segments of repeated and random spans
    out = bytearray()
    while len(out) < total:
        remain = total - len(out)
        kind = rng.choice(["repeat", "random", "zeros", "incr"])
        span = min(remain, rng.randint(1, max(1, remain)))
        if kind == "repeat":
            out.extend(_pattern_repeat(rng.randrange(256), span))
        elif kind == "random":
            out.extend(_rand(rng, span))
        elif kind == "zeros":
            out.extend(b"\x00" * span)
        else:  # incr pattern 0..255 wrap
            start = rng.randrange(256)
            out.extend(bytes(((start + i) & 0xFF) for i in range(span)))
    return bytes(out)


def _mix_sections(rng: random.Random, total: int) -> bytes:
    # Compose a file of several sections with tiny headers to vary locality
    sections: List[bytes] = []
    produced = 0
    while produced < total:
        remain = total - produced
        section_len = min(remain, rng.randint(8, max(8, remain)))
        tag = rng.choice([b"RAND", b"ZERO", b"REPT", b"ALTN", b"TEXT", b"BINA"])  # 4-5 bytes
        if tag == b"RAND":
            body = _rand(rng, section_len)
        elif tag == b"ZERO":
            body = b"\x00" * section_len
        elif tag == b"REPT":
            body = _pattern_repeat(rng.randrange(256), section_len)
        elif tag == b"ALTN":
            body = _alternating(rng.randrange(256), rng.randrange(256), section_len)
        elif tag == b"TEXT":
            # Mostly printable ASCII with occasional control chars
            body = bytes((rng.choice([rng.randrange(32, 127), 10, 13, 9, 0])) for _ in range(section_len))
        else:
            body = _rle_segments(rng, section_len)
        # Simple 4-byte little-endian length header (valid struct format)
        header = struct.pack("<I", len(body))
        chunk = header + tag + body
        # Truncate to fit requested total
        chunk = chunk[:section_len]
        sections.append(chunk)
        produced += len(chunk)
    return b"".join(sections)[:total]


def _choose_size(rng: random.Random) -> int:
    # Favor interesting sizes including edge cases and page boundaries
    choices = [
        0,
        1, 2, 3, 7, 8, 15, 16, 31, 32,
        63, 64, 127, 128, 255, 256,
        PAGE - 1, PAGE, PAGE + 1,
        1024, 2048, 3072, 3500, 4000, MAX_SIZE,
    ]
    if rng.random() < 0.6:
        choices.append(rng.randint(0, MAX_SIZE))
    size = rng.choice(choices)
    return max(0, min(MAX_SIZE, size))


def _build_content(rng: random.Random, size: int) -> bytes:
    if size == 0:
        return b""
    strategy = rng.choices(
        [
            "random",
            "zeros",
            "ones",
            "alt",
            "rle",
            "mixed",
            "header_body",
        ],
        weights=[25, 10, 5, 10, 20, 20, 10],
        k=1,
    )[0]
    if strategy == "random":
        return _rand(rng, size)
    if strategy == "zeros":
        return b"\x00" * size
    if strategy == "ones":
        return b"\xFF" * size
    if strategy == "alt":
        return _alternating(rng.randrange(256), rng.randrange(256), size)
    if strategy == "rle":
        return _rle_segments(rng, size)
    if strategy == "mixed":
        return _mix_sections(rng, size)
    # header_body: small header with declared size followed by payload; still arbitrary bytes overall
    header_extra = min(12, max(0, size - 4))
    header = struct.pack("<I", size) + _rand(rng, header_extra)
    payload_len = max(0, size - len(header))
    payload = _rle_segments(rng, payload_len)
    return (header + payload)[:size]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    size = _choose_size(rng)
    content = _build_content(rng, size)
    assert len(content) == size
    return content
